# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Use safety gating, confidence confirmation, hysteretic steering, and bounded reacquisition.

    The controller stops on unsafe conditions, briefly verifies new tracks,
    reacquires lost targets with alternating scans, and otherwise approaches
    the confirmed target while suppressing unnecessary left/right oscillation.
    """
    memory = dict(memory or {})
    state = memory.get("state", "IDLE")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")
    last_action = memory.get("last_action", "")

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_confidence = float(observation["target_confidence"])
    identity_confidence = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety_confidence = float(observation["safety_confidence"])
    closing_risk = float(observation["closing_risk"])
    heading_error = abs(float(observation["heading_error"]))

    def emit(action, confidence, next_state):
        """Persist only compact controller state and return the required action tuple."""
        memory["state"] = next_state
        memory["last_action"] = action
        return action, confidence, memory

    # Hard safety gate.
    if safety_confidence < 0.60 or closing_risk >= 0.75:
        return emit("STOP", 0.99, "STOPPED")

    confirmed = (
        visible
        and target_confidence >= 0.55
        and identity_confidence >= 0.60
    )

    if not confirmed:
        if state in {"LOCKED", "APPROACH", "VERIFY", "REACQUIRE"} or lost_steps > 0:
            if lost_steps <= 1:
                return emit("STOP", 0.92, "REACQUIRE")
            action = scan_direction
            memory["scan_direction"] = (
                "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
            )
            return emit(action, 0.75, "SEARCH")
        return emit(scan_direction, 0.75, "SEARCH")

    # Require a short stable track before committing to motion.
    if track_age < 2:
        return emit("SLOW_DOWN", 0.80, "VERIFY")

    if distance == "near":
        if heading_error <= 15.0 and identity_confidence >= 0.80:
            return emit("ARRIVED", 0.96, "ARRIVED")

        # At close range, prioritize target bearing for final alignment.
        if bearing < -8.0 and observation["corridor_left"]:
            return emit("VEER_LEFT", 0.88, "APPROACH")
        if bearing > 8.0 and observation["corridor_right"]:
            return emit("VEER_RIGHT", 0.88, "APPROACH")
        if observation["corridor_center"] and heading_error <= 25.0:
            return emit("FORWARD", 0.84, "APPROACH")

    # Hysteresis: do not reverse steering for small noisy bearing changes.
    desired = ""
    if bearing < -12.0 and observation["corridor_left"]:
        desired = "VEER_LEFT"
    elif bearing > 12.0 and observation["corridor_right"]:
        desired = "VEER_RIGHT"
    elif observation["corridor_center"] and abs(bearing) <= 18.0:
        desired = "FORWARD"
    elif observation["corridor_left"] and bearing <= 0.0:
        desired = "VEER_LEFT"
    elif observation["corridor_right"] and bearing >= 0.0:
        desired = "VEER_RIGHT"

    if desired == "VEER_LEFT" and last_action == "VEER_RIGHT" and abs(bearing) < 18.0:
        desired = "FORWARD" if observation["corridor_center"] else ""
    elif desired == "VEER_RIGHT" and last_action == "VEER_LEFT" and abs(bearing) < 18.0:
        desired = "FORWARD" if observation["corridor_center"] else ""

    if desired:
        return emit(desired, 0.90 if desired != "FORWARD" else 0.88, "APPROACH")

    return emit("STOP", 0.98, "STOPPED")
# EVOLVE-BLOCK-END
